<?php
require __DIR__.'/config.php';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $cart=json_decode($_POST['cart']??'[]',true);if(!is_array($cart)||!count($cart)){flash('Add at least one medicine before creating a bill.','error');redirect('billing.php');}
 try{$pdo->beginTransaction();$lines=[];$subtotal=0;foreach($cart as $line){$id=(int)($line['id']??0);$qty=max(1,(int)($line['qty']??1));$q=$pdo->prepare('SELECT id,name,price,stock_qty FROM medicines WHERE id=? AND active=1 FOR UPDATE');$q->execute([$id]);$m=$q->fetch();if(!$m)throw new RuntimeException('A medicine in this bill is no longer available.');if($qty>(int)$m['stock_qty'])throw new RuntimeException('Not enough stock for '.$m['name'].'. Available: '.$m['stock_qty'].'.');$amount=$qty*(float)$m['price'];$subtotal+=$amount;$lines[]=[$m,$qty,$amount];}
 $discount=max(0,(float)($_POST['discount']??0));$taxRate=max(0,(float)($_POST['tax_rate']??0));$tax=round(max(0,$subtotal-$discount)*$taxRate/100,2);$total=max(0,$subtotal-$discount)+$tax;$invoice='MS-'.date('ymd').'-'.str_pad((string)random_int(1,9999),4,'0',STR_PAD_LEFT);$pdo->prepare('INSERT INTO sales(invoice_no,customer_name,customer_phone,subtotal,discount,tax_rate,tax,total,payment_method) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$invoice,trim($_POST['customer_name']??''),trim($_POST['customer_phone']??''),$subtotal,$discount,$taxRate,$tax,$total,$_POST['payment_method']??'Cash']);$saleId=(int)$pdo->lastInsertId();$insert=$pdo->prepare('INSERT INTO sale_items(sale_id,medicine_id,medicine_name,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?)');$stock=$pdo->prepare('UPDATE medicines SET stock_qty=stock_qty-? WHERE id=?');foreach($lines as [$m,$qty,$amount]){$insert->execute([$saleId,$m['id'],$m['name'],$qty,$m['price'],$amount]);$stock->execute([$qty,$m['id']]);}$pdo->commit();redirect('invoice.php?id='.$saleId);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Could not save bill. Check database setup.','error');redirect('billing.php');}
}
$medicines=$pdo->query('SELECT id,name,generic_name,strength,unit,price,stock_qty FROM medicines WHERE active=1 AND stock_qty>0 ORDER BY name')->fetchAll();$pageTitle='Billing';require __DIR__.'/partials/header.php';
?>
<div class="welcome"><div><div class="eyebrow">POINT OF SALE</div><h1>Create a bill</h1><p>Build the customer’s order and print a clean invoice.</p></div><a class="button secondary" href="index.php">← Overview</a></div>
<form method="post" id="bill-form" class="billing-layout"><input type="hidden" name="cart" id="cart-input"><section class="panel bill-products"><div class="panel-heading"><div><div class="eyebrow">PRODUCTS</div><h2>Choose medicines</h2></div><span class="item-count" id="available-count"><?= count($medicines) ?> available</span></div><div class="search product-search"><input id="medicine-search" placeholder="Search by medicine name…"><span>⌕</span></div><div class="product-list" id="product-list"><?php foreach($medicines as $m): ?><button type="button" class="product-option" data-id="<?= $m['id'] ?>" data-name="<?= h($m['name'].' '.($m['strength']??'')) ?>" data-price="<?= h($m['price']) ?>" data-stock="<?= (int)$m['stock_qty'] ?>" data-unit="<?= h($m['unit']) ?>"><span class="product-plus">＋</span><span class="product-copy"><b><?= h($m['name']) ?></b><small><?= h(trim(($m['strength']??'').' · '.($m['generic_name']??''),' ·')) ?></small><em><?= (int)$m['stock_qty'] ?> <?= h($m['unit']) ?> available</em></span><strong><?= money($m['price']) ?></strong></button><?php endforeach; ?><?php if(!$medicines): ?><div class="empty">No medicines in stock yet. Add inventory first.</div><?php endif; ?></div></section>
<aside class="panel bill-summary"><div class="eyebrow">CHECKOUT</div><h2>Current bill</h2><div class="customer-fields"><label>Customer name<input name="customer_name" placeholder="Walk-in customer"></label><label>Phone number<input name="customer_phone" type="tel" placeholder="Optional"></label></div><div class="cart-heading"><span>Items</span><span id="cart-count">0 items</span></div><div id="cart-items" class="cart-items"><div class="cart-empty">Add a medicine to start the bill.</div></div><div class="bill-adjustments"><label>Discount (₹)<input type="number" name="discount" id="discount" min="0" step="0.01" value="0"></label><label>Tax (%)<input type="number" name="tax_rate" id="tax-rate" min="0" max="100" step="0.01" value="0"></label></div><label class="payment-label">Payment method<select name="payment_method"><option>Cash</option><option>UPI</option><option>Card</option><option>Other</option></select></label><div class="totals"><div><span>Subtotal</span><b id="subtotal">₹0.00</b></div><div><span>Discount</span><b id="discount-total">− ₹0.00</b></div><div><span>Tax</span><b id="tax-total">₹0.00</b></div><div class="grand-total"><span>Total due</span><b id="total">₹0.00</b></div></div><button class="button checkout-button" type="submit">Create bill <span>→</span></button><p class="checkout-note">Stock updates automatically after billing.</p></aside></form>
<script>window.mediStoreMoney = <?= json_encode(array_column($medicines,'price','id')) ?>;</script>
